      "path": "src/client/index.tsx",
      "content": "/**\n * Browser half entry point — `exports[\"./client\"]`, served by the shell at\n * `/plugins/dsh-openviking-enhance/client.js` and executed as a lazy-CJS\n * factory (`window.__ModuleLoader__.load({id, factory})`, see `build.mjs`).\n *\n * Failure policy: DOM and slot problems are logged, never thrown. A plugin whose\n * `apply` throws fails the whole web shell boot, and an external plugin must not\n * be able to take the GUI down. Every registration is owned by the mount table\n * below (or by `ctx.effect`), so an unload — or a feature switch — collapses it\n * cleanly and can mount it again later.\n *\n * Slot map, all verified against `@deepseek-ai/dsh-client-ui-{slots,sidebar,layout,conversation}@0.2.0-rc.2`,\n * and re-verified on 0.2.1-rc.2 and 0.2.1-rc.3:\n *   sidebar.panellist          list, root      owner {size, active}  → panel icon\n *   main                       keyed, root     key must equal the panellist id\n *   conversation.composer.dock list, session   inject(sessionId)     → status pill\n *\n * Plus one tab type in the right Sidebar\n * (`@deepseek-ai/dsh-client-ui-sidebar-right@0.2.0-rc.2`, re-verified on\n * 0.2.1-rc.2 and 0.2.1-rc.3), registered in two\n * stages because that is the only contract the framework offers:\n *   ctx.sidebarRightTabs.register({id, kind, title, guide})   stage one: a page type\n *   sidebar.right.pane.tab     keyed, session, key = that id → stage two: the body\n *\n * The three surfaces are switchable from the plugin's own settings form\n * (`showSidebarEntry` / `showCommitStatus` / `showRecallPanel`). `feature-toggles.ts`\n * reads the live values from `ctx.configForms`; this file owns the mount/unmount\n * pairs and the order they run in:\n *\n *  - mount: main panel before the sidebar row that opens it, because a row whose\n *    `main` key is not registered throws when selected;\n *  - unmount: the row before the main panel (the layout notices the key vanish\n *    and returns to the conversation by itself); the recall tab drops its body\n *    and then its type, while the switch additionally closes an open recall page\n *    (immediately when a surface is mounted, otherwise on its return);\n *  - `plugins.row.config` is registered unconditionally: the Configure form is\n *    the only way back after a surface has been hidden, so it must never be\n *    behind a switch itself.\n */\nimport type {\n  ClientContext,\n  SidebarRightService,\n  SidebarRightTabRecord,\n  SidebarRightTabRegistry,\n} from './slot-service.ts'\nimport { installStyles } from './styles.ts'\nimport { OpenVikingIcon } from './openviking-icon.tsx'\nimport { StudioPanel } from './studio-panel.tsx'\nimport { CommitStatusPill } from './commit-status.tsx'\nimport { RecallPanel } from './recall-panel.tsx'\nimport { ConfigPage } from './config-page.tsx'\nimport { attachLocale, t } from './locale.ts'\nimport {\n  DEFAULT_FEATURE_FLAGS,\n  FEATURE_ORDER,\n  watchFeatureFlags,\n  type FeatureFlags,\n} from './feature-toggles.ts'\n\n/** Client services this half waits for before `apply` runs. */\nexport const inject = ['slots']\n\n/** Sidebar row id; the same value keys the `main` panel entry. */\nconst PANEL_ID = 'openviking'\n\n/**\n * Sort key of our sidebar row.\n *\n * The sidebar orders `sidebar.panellist` ascending by `order` and, on a tie, falls\n * back to registration order — which is plugin load order and therefore differs\n * between boots. That is exactly what made this row drift: it shared `order: 30`\n * with the skill-explorer row, so it sometimes sat before it and sometimes after.\n *\n * The values in use are 0 and 10 (the shell's own plugin and schedule rows), 20\n * (task board), 30 (skill explorer), and the framework's own contract doc shows\n * `order: 100` for a third-party panel row. This row is meant to be last, so it\n * sits well above all of those; a plain \"just above the current maximum\" value\n * would collide again with the next plugin that picks it.\n */\nconst SIDEBAR_ORDER = 1000\n\n/**\n * The right Sidebar tab type.\n *\n * `id` is the implementation's identity and is what the framework keys the body\n * and title seats by; `kind` is what `ctx.sidebarRight.openTab(kind)` names. Both\n * are namespaced because the key domain is open: another plugin could register a\n * `recall` kind, and a collision on `id` throws.\n */\nconst RECALL_TAB_ID = 'dsh-openviking-enhance:recall'\nconst RECALL_TAB_KIND = 'openviking-recall'\n\n/**\n * The address a page tab is recorded under (`sidebar://<kind>`). Hiding the\n * recall surface closes the page first when it is the one on screen, so the\n * column does not keep a record whose body and type no longer exist.\n */\nconst RECALL_PAGE_ADDRESS = `sidebar://${RECALL_TAB_KIND}`\n\n/**\n * The plugin's own row on the Plugins page.\n *\n * The page keys the config seat by `<package name>#<row id>`, taken from the\n * bundle's manifest and its patch, and the **Configure** control appears only\n * because a registration exists here. Nothing else in DSH renders a form for a\n * plugin's Config, however well declared the schema is.\n *\n * `PACKAGE_NAME` is written out because the browser half has no package.json to\n * read; `scripts/smoke-client.mjs` asserts it equals the manifest's name. The row\n * id is also the settings namespace DSH serves the entry's form under, which is\n * why `configForms.get()` is given it directly rather than derived again.\n */\nconst PACKAGE_NAME = 'dsh-openviking-enhance'\nconst ROW_ID = 'openviking-enhance'\nconst CONFIG_ROW_KEY = `${PACKAGE_NAME}#${ROW_ID}`\nconst SETTINGS_NAMESPACE = ROW_ID\n\n/**\n * Sidebar row glyph. The shell hands a list occupant only `{ size, active }` and\n * draws the button, title and highlight itself, so this adds just the marker the\n * panel row carries and defers the artwork to the shared mark — the same one the\n * status pill uses.\n */\nfunction SidebarIcon(props: { size: number; active: boolean }) {\n  return <OpenVikingIcon {...props} data-dsh-panel-entry={PANEL_ID} />\n}\n\nfunction report(context: ClientContext, error: unknown): void {\n  const message = error instanceof Error ? error.message : String(error)\n  const logger = context.logger\n  if (typeof logger?.warn === 'function') logger.warn(`[openviking-enhance] ${message}`, error)\n  else console.error('[openviking-enhance]', error)\n}\n\n/**\n * Whether one right-Sidebar record is the recall page this plugin contributed.\n *\n * The live record is `{ id, kind, contentId, title }` and a page tab's address\n * (`sidebar://<kind>`) is `contentId`. Comparing only a field named `address`\n * (which the framework does not send) is what made the first cut of this switch\n * leave a dead recall tab behind: the check was always false, so `close()` never\n * ran. Match the content identity first, then the kind, and keep the legacy\n * field as a fallback for harness versions that sent it.\n */\nfunction isRecallPage(tab: SidebarRightTabRecord): boolean {\n  return (\n    tab.contentId === RECALL_PAGE_ADDRESS ||\n    tab.kind === RECALL_TAB_KIND ||\n    tab.address === RECALL_PAGE_ADDRESS\n  )\n}\n\n/**\n * Close the recall page when it is the one the right Sidebar is showing.\n *\n * Returns whether a close was issued. Best effort on purpose: the service may be\n * absent, or — the common case when the user edits the settings form — there may\n * be no mounted right-Sidebar surface at all while a Plugins page fills the main\n * column, so `active()` answers `undefined`. Callers arm a deferred retry for\n * that case.\n */\nfunction tryCloseRecallTab(\n  context: ClientContext,\n  sidebarRight: SidebarRightService | undefined,\n): boolean {\n  if (sidebarRight === undefined) return false\n  try {\n    const active = sidebarRight.active?.()\n    if (active === undefined || !isRecallPage(active)) return false\n    sidebarRight.close?.(active.id)\n    return true\n  } catch (error) {\n    report(context, error)\n    return false\n  }\n}\n\nexport function apply(context: ClientContext): void {\n  const disposers: Array<() => void> = []\n  /** Live mounts, keyed by the switch that owns them. */\n  const mounted = new Map<keyof FeatureFlags, () => void>()\n\n  // The app's language, for every string this half renders. Read live by `t()`,\n  // so switching the app's locale does not need a reload.\n  //\n  // Attached through a SCOPED injection, not a property read.\n  //\n  // Reading `context.locale` throws (`cannot get property \"locale\" without\n  // inject`) and, sitting outside every `try`, it took the whole entry down: no\n  // sidebar row, no commit pill, no recall tab. Reading it through the plain\n  // `get()` accessor is legal but does not reach it either — the form then fell\n  // back to `navigator.language`, so the plugin spoke the browser's language\n  // instead of the app's. This is the same two-stage pattern the recall tab uses\n  // for its registry, and for the same reason: the callback runs when the service\n  // exists and is never a dependency the entry waits on.\n  context.inject(['locale'], (scope) => {\n    attachLocale(scope.get('locale') as Parameters<typeof attachLocale>[0])\n  })\n\n  try {\n    installStyles()\n  } catch (error) {\n    report(context, error)\n  }\n\n  /**\n   * The right Sidebar's outward face, kept for the recall mount to close that\n   * tab on the way out. Optional like the settings service: a composition\n   * without it keeps the recall surface, it just cannot pre-close the page.\n   */\n  let sidebarRight: SidebarRightService | undefined\n  try {\n    const watch = context.inject(['sidebarRight'], (scope) => {\n      sidebarRight = scope.get('sidebarRight') as SidebarRightService | undefined\n      return () => {\n        sidebarRight = undefined\n      }\n    })\n    disposers.push(() => watch.dispose())\n  } catch (error) {\n    report(context, error)\n  }\n\n  const slots = context.slots\n\n  /**\n   * A recall-page close that has to wait for the right Sidebar to come back.\n   *\n   * The settings form lives on the Plugins page, and that page fills the main\n   * column: while it is open the conversation — and with it the right Sidebar's\n   * mounted surface — is unmounted, so `sidebarRight.active()` answers\n   * `undefined` and the open recall page cannot be found at save time. The switch\n   * still unmounts the surface immediately; this set remembers to close the page\n   * as soon as the column is mounted again. Re-enabling the switch, or unloading\n   * the plugin, cancels the pending work.\n   */\n  const pendingRecallCloses = new Set<() => void>()\n\n  function cancelPendingRecallCloses(): void {\n    for (const cancel of [...pendingRecallCloses]) {\n      pendingRecallCloses.delete(cancel)\n      try {\n        cancel()\n      } catch (error) {\n        report(context, error)\n      }\n    }\n  }\n\n  function armRecallTabClose(): void {\n    const right = sidebarRight\n    if (right === undefined) return\n    // The surface may actually be mounted (another window, a hot reload): try\n    // once before subscribing.\n    if (tryCloseRecallTab(context, right)) return\n    const mounted = right.mounted\n    if (mounted === undefined || typeof mounted.subscribe !== 'function') return\n\n    let stopped = false\n    let unsubscribe: (() => void) | undefined\n    let timer: ReturnType<typeof setTimeout> | undefined\n    const stop = () => {\n      if (stopped) return\n      stopped = true\n      if (timer !== undefined) clearTimeout(timer)\n      timer = undefined\n      try {\n        unsubscribe?.()\n      } catch (error) {\n        report(context, error)\n      }\n      unsubscribe = undefined\n      pendingRecallCloses.delete(stop)\n    }\n    // The mounted Session changes before React renders the arriving commit, so\n    // the store the tab record lives in may not be adopted yet at notification\n    // time. A handful of short retries covers that gap without a poll forever.\n    const attempt = (remaining: number): void => {\n      if (stopped) return\n      if (tryCloseRecallTab(context, right)) {\n        stop()\n        return\n      }\n      if (remaining <= 0) {\n        stop()\n        return\n      }\n      timer = setTimeout(() => attempt(remaining - 1), 60)\n    }\n    try {\n      unsubscribe = mounted.subscribe(() => attempt(6))\n    } catch (error) {\n      report(context, error)\n      return\n    }\n    pendingRecallCloses.add(stop)\n  }\n\n  /**\n   * The Studio surface: the left sidebar row and the centre page it opens.\n   *\n   * Main first, then the row — a row is clickable the moment it exists, and\n   * selecting one whose `main` key is not registered throws in the shell.\n   */\n  function mountSidebarEntry(): () => void {\n    const disposeMain = slots.inject('main', () =>\n      slots.register({ name: 'main', key: PANEL_ID }, StudioPanel),\n    )\n    const disposeRow = slots.inject('sidebar.panellist', () =>\n      slots.register(\n        {\n          name: 'sidebar.panellist',\n          id: PANEL_ID,\n          order: SIDEBAR_ORDER,\n          label: () => 'OpenViking',\n        },\n        SidebarIcon,\n      ),\n    )\n    return () => {\n      // Row first: the layout reacts to the `main` key disappearing by returning\n      // to the conversation, so dropping the page while the row still points at\n      // it would leave a row that throws when clicked for one render.\n      disposeRow()\n      disposeMain()\n    }\n  }\n\n  /**\n   * The session footer status pill. The inject factory receives the session id\n   * because the slot is session-scoped. `order: 1` places it after the shell's\n   * stats pills and the context meter; the row keeps its own centring.\n   */\n  function mountCommitStatus(): () => void {\n    return slots.inject('conversation.composer.dock', () =>\n      slots.register(\n        {\n          name: 'conversation.composer.dock',\n          id: 'openviking-commit',\n          order: 1,\n          inject: (sessionId: string) => ({ sessionId }),\n        },\n        CommitStatusPill,\n      ),\n    )\n  }\n\n  /**\n   * The right Sidebar tab, contributed in the two stages the framework asks for.\n   *\n   * Waiting on the REGISTRY (a service), not on the slot declaration, is\n   * load-bearing: the right Sidebar's own seat declares\n   * `sidebar.right.pane.tab` before it provides `sidebarRightTabs`, so a\n   * registration triggered by the declaration would read the registry as absent\n   * and — because a declaration never collapses — never retry.\n   */\n  function mountRecallPanel(): () => void {\n    const seat = context.inject(['sidebarRightTabs'], (scope) => {\n      const tabs = scope.get('sidebarRightTabs') as SidebarRightTabRegistry | undefined\n      if (tabs === undefined) return\n      const disposeType = tabs.register({\n        id: RECALL_TAB_ID,\n        kind: RECALL_TAB_KIND,\n        title: () => t('recall.tabTitle'),\n        // The guide is how the tab is found at all: the right Sidebar opens on its\n        // guide page, and a type with no entry there is reachable only by code.\n        guide: [\n          {\n            id: 'recall',\n            order: 40,\n            title: () => t('recall.tabTitle'),\n            description: () => t('recall.tabDescription'),\n          },\n        ],\n      })\n      try {\n        // Stage two: the body, keyed by the type's own id (that is what the\n        // framework dispatches on). Registered on the slot declaration, which the\n        // right Sidebar has certainly made by the time its registry exists.\n        const disposeBody = slots.inject('sidebar.right.pane.tab', () =>\n          slots.register(\n            {\n              name: 'sidebar.right.pane.tab',\n              key: RECALL_TAB_ID,\n              inject: (sessionId: string) => ({ sessionId }),\n            },\n            RecallPanel,\n          ),\n        )\n        return () => {\n          // Drop the body before the type: the registry refuses a second\n          // registration of the same id for the rest of the page's life, and a\n          // type whose body is missing renders the framework's dead-page notice.\n          // Closing an open page is the switch's job (`applyFeature`), not this\n          // teardown's: a plugin unload or HMR reload must not discard the tab\n          // the user had open.\n          disposeBody()\n          disposeType()\n        }\n      } catch (error) {\n        // A body that failed to register must not leave the type claimed: the\n        // registry refuses a second registration of the same id for the rest of\n        // the page's life.\n        disposeType()\n        throw error\n      }\n    })\n    return () => seat.dispose()\n  }\n\n  const mounts: Record<keyof FeatureFlags, () => () => void> = {\n    sidebarEntry: mountSidebarEntry,\n    commitStatus: mountCommitStatus,\n    recallPanel: mountRecallPanel,\n  }\n\n  /** Mount or unmount one surface; a mount failure is logged, never thrown. */\n  function applyFeature(feature: keyof FeatureFlags, on: boolean): void {\n    const live = mounted.get(feature)\n    if (on && live === undefined) {\n      // A surface that is coming back cancels a \"close the stale page\" retry\n      // armed when it went away: the page may be the user's own, restored.\n      if (feature === 'recallPanel') cancelPendingRecallCloses()\n      try {\n        mounted.set(feature, mounts[feature]())\n      } catch (error) {\n        report(context, error)\n      }\n      return\n    }\n    if (!on && live !== undefined) {\n      mounted.delete(feature)\n      // Only the switch closes the recall page (see the mount's teardown for why\n      // an unload must not). When the settings form is what did the hiding, the\n      // right Sidebar is unmounted, so the close is retried on its return.\n      const closed = feature === 'recallPanel' ? tryCloseRecallTab(context, sidebarRight) : false\n      try {\n        live()\n      } catch (error) {\n        report(context, error)\n      }\n      if (feature === 'recallPanel' && !closed) armRecallTabClose()\n    }\n  }\n\n  /** Apply one settings answer to every surface. */\n  function applyFlags(flags: FeatureFlags): void {\n    for (const feature of FEATURE_ORDER) applyFeature(feature, flags[feature])\n  }\n\n  // Start from the pre-switch behaviour: everything on. A settings answer that\n  // arrives later (or a stored `false`) turns the chosen surfaces off; one that\n  // never arrives leaves the plugin exactly as it shipped.\n  applyFlags(DEFAULT_FEATURE_FLAGS)\n\n  // Watch the switches for the rest of the page's life. The callback runs when a\n  // ready snapshot is already held, so a persisted `false` applies on boot too.\n  let stopWatching = (): void => {}\n  try {\n    stopWatching = watchFeatureFlags(context, SETTINGS_NAMESPACE, applyFlags)\n  } catch (error) {\n    report(context, error)\n  }\n\n  // The plugin's own settings, on its row of the Plugins page. Registered\n  // unconditionally — this form is where a hidden surface is switched back on.\n  try {\n    disposers.push(\n      context.slots.inject('plugins.row.config', () =>\n        context.slots.register({ name: 'plugins.row.config', key: CONFIG_ROW_KEY }, ConfigPage),\n      ),\n    )\n  } catch (error) {\n    report(context, error)\n  }\n\n  context.effect(\n    () => () => {\n      // Stop observing first: an unload must not race a settings answer into\n      // mounting a surface while the mounts below are being torn down.\n      try {\n        stopWatching()\n      } catch (error) {\n        report(context, error)\n      }\n      // An unload must not fire a deferred close after the surfaces are gone.\n      cancelPendingRecallCloses()\n      for (const feature of [...FEATURE_ORDER].reverse()) {\n        const live = mounted.get(feature)\n        if (live === undefined) continue\n        mounted.delete(feature)\n        try {\n          live()\n        } catch (error) {\n          report(context, error)\n        }\n      }\n      for (const dispose of disposers.splice(0)) {\n        try {\n          dispose()\n        } catch (error) {\n          report(context, error)\n        }\n      }\n    },\n    'openviking-enhance: ui mounts',\n  )\n}\n"
    },
    {
      "path": "src/host/index.ts",
      "content": "/**\n * Host half of `dsh-openviking-enhance`.\n *\n * Responsibilities:\n *  1. resolve the local OpenViking connection (same files the CLI reads);\n *  2. expose read-only JSON routes on the DSH web server for the browser half —\n *     config, commit status, commit list, one commit's memory diff, the current\n *     session's retrieval, and one retrieved entry's full text;\n *  3. stay completely inert when OpenViking is not running: every route answers\n *     `{ok:false, error}` instead of throwing, because a plugin route that\n *     throws can take a request down with it.\n *\n * It deliberately performs **no writes** to OpenViking and never touches the\n * third-party memory plugin's objects; the only cross-plugin reads are the two\n * optional lookups documented in `commit-service.ts`.\n */\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport {\n  API_PREFIX,\n  RECALL_DEFAULT_LIMIT,\n  TIMELINE_DEFAULT,\n  TIMELINE_MAX,\n  type ApiResult,\n  type EnhanceConfig,\n  type PluginNotice,\n} from '../shared/protocol.ts'\nimport { describeConnection, resolveConnection } from './config.ts'\nimport { isLoopbackHostname, isTrustedLocalRequest } from './trust-fence.ts'\nimport { CommitService, isArchiveUriForSession, type OpenVikingMemoryRuntime } from './commit-service.ts'\nimport { OpenVikingApi } from './openviking-api.ts'\nimport { RecallService } from './recall-service.ts'\n\n/** Cordis plugin name used by loader diagnostics. */\nexport const name = 'openviking-enhance'\n\n/** The web server is the only hard requirement; the OpenViking plugin is optional. */\nexport const inject = ['webServer']\n\n/**\n * Everything a user may want to change, marked `.volatile()`.\n *\n * That marker is what puts a field on the Plugins page's configuration form: the\n * settings service projects volatile fields only, and a plugin whose fields are\n * ordinary has no form at all — its configuration stays in `cordis.patch.yml`,\n * which is exactly the situation this plugin shipped with. An empty string means\n * \"not overridden\", so the defaults below stay the composition layer the form\n * reverts to when a field is cleared.\n */\nexport const Config = z.object({\n  /** Override the OpenViking base URL; default comes from `~/.openviking/ovcli.conf`. */\n  endpoint: z.string().default('').volatile(),\n  /** Override the API key (prefer the config file; this is for unusual setups). */\n  apiKey: z.string().default('').volatile(),\n  /** Override the identity the panel reads under. */\n  account: z.string().default('').volatile(),\n  user: z.string().default('').volatile(),\n  /** Studio path appended to the endpoint when building the iframe URL. */\n  studioPath: z.string().default('/studio/').volatile(),\n  /** Status cache TTL in milliseconds. */\n  cacheTtlMs: z.number().default(2500).volatile(),\n  /** How long one retrieval answer is reused, in milliseconds. */\n  recallCacheTtlMs: z.number().default(15000).volatile(),\n  /**\n   * Interface switch: the Studio entry in the left sidebar.\n   *\n   * The three `show*` fields are *client-only* preferences: they exist here so the\n   * Plugins page's configuration form can render and persist them (the settings\n   * service projects `.volatile()` fields only), and the host half never reads\n   * them. The browser half watches them through `ctx.configForms` and mounts or\n   * unmounts each surface live, so flipping one takes effect on the next save\n   * without a reload.\n   */\n  showSidebarEntry: z.boolean().default(true).volatile(),\n  /** Interface switch: the per-session commit status pill under the composer. */\n  showCommitStatus: z.boolean().default(true).volatile(),\n  /** Interface switch: the Memory recall tab in the right sidebar. */\n  showRecallPanel: z.boolean().default(true).volatile(),\n})\n\n/**\n * One `Config` field as the Loader actually hands it over.\n *\n * A field marked `.volatile()` — which is what makes it editable on the Plugins\n * page — does NOT arrive as its value: schemastery resolves it to a reference\n * whose `get()` reads the current one, so a change made in the form is visible\n * without a reload. Reading such a field directly is exactly how this plugin\n * failed to activate the first time it shipped a settings form:\n * `config.studioPath` was a reference, `(path ?? '').trim` threw from inside\n * `apply`, and the whole entry went down with it.\n *\n * Ordinary fields arrive as plain values, so this accepts both — and typing the\n * parameter this way is the point: the compiler now refuses a raw read.\n */\nexport type ConfigField<T> = T | { get(): T }\n\nexport interface EnhanceConfigInput {\n  endpoint?: ConfigField<string>\n  apiKey?: ConfigField<string>\n  account?: ConfigField<string>\n  user?: ConfigField<string>\n  studioPath?: ConfigField<string>\n  cacheTtlMs?: ConfigField<number>\n  recallCacheTtlMs?: ConfigField<number>\n}\n\n/** The value behind a field, whether it is a reference or the value itself. */\nexport function configField<T>(value: ConfigField<T> | undefined): T | undefined {\n  if (value === null || value === undefined) return undefined\n  if (typeof value === 'object' && typeof (value as { get?: unknown }).get === 'function') {\n    return (value as { get(): T }).get()\n  }\n  return value as T\n}\n\n/** A string field, or `''` for anything that is not one. */\nfunction configText(value: ConfigField<string> | undefined): string {\n  const plain = configField(value)\n  return typeof plain === 'string' ? plain : ''\n}\n\n/** A numeric field, or the fallback. */\nfunction configNumber(value: ConfigField<number> | undefined, fallback: number): number {\n  const plain = configField(value)\n  return typeof plain === 'number' && Number.isFinite(plain) ? plain : fallback\n}\n\n/** Structural view of the host services this plugin uses. */\ninterface WebRoute {\n  kind: 'exact' | 'prefix'\n  path: string\n  handler: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>\n}\n\n/**\n * The host context, narrowed to what this plugin touches. It is deliberately not\n * `extends Context`: the real logger is Cordis's `LoggerService`, and widening or\n * narrowing it here would only create friction with the framework's own types.\n */\ninterface HostContext {\n  webServer: { register(route: WebRoute): () => void; port: number }\n  effect(callback: () => (() => void) | void, label?: string): () => void\n  get(key: string): unknown\n  logger?: { info?(message: string): void; warn?(message: string, error?: unknown): void }\n}\n\nfunction writeJson(res: ServerResponse, status: number, body: unknown): void {\n  const payload = JSON.stringify(body)\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'cache-control': 'no-store',\n    'content-length': Buffer.byteLength(payload),\n  })\n  res.end(payload)\n}\n\n/**\n * An `http(s)` endpoint on this machine, or null.\n *\n * A candidate that is not loopback is refused rather than normalized: the point\n * of the check is that a request this plugin makes cannot leave the machine.\n */\nexport function parseLoopbackEndpoint(raw: string): URL | null {\n  const trimmed = raw.trim()\n  if (trimmed.length === 0) return null\n  let url: URL\n  try {\n    url = new URL(trimmed)\n  } catch {\n    return null\n  }\n  if (url.protocol !== 'http:' && url.protocol !== 'https:') return null\n  return isLoopbackHostname(url.hostname) ? url : null\n}\n\nfunction query(req: IncomingMessage): URLSearchParams {\n  return new URL(req.url ?? '/', 'http://127.0.0.1').searchParams\n}\n\n/**\n * A plugin entry that throws while activating does not just fail: it takes the\n * whole profile with it, and the user gets \"1 entry did not activate\" plus an\n * application that will not start. This plugin is a viewer for a local memory\n * server — there is no version of that worth a dead boot — so activation is\n * wrapped: a failure is logged in full and the plugin simply provides nothing.\n *\n * The logging is not decoration. The first time this happened the only visible\n * symptom was the boot dialog, and the cause had to be reconstructed by hand.\n */\nexport function apply(ctx: Context, config: EnhanceConfigInput = {}): void {\n  try {\n    start(ctx, config)\n  } catch (error) {\n    const logger = (ctx as unknown as { logger?: { error?: (line: string) => void } }).logger\n    const detail = error instanceof Error ? (error.stack ?? error.message) : String(error)\n    logger?.error?.(`[openviking-enhance] failed to activate, so the plugin provides nothing: ${detail}`)\n  }\n}\n\nfunction start(ctx: Context, config: EnhanceConfigInput): void {\n  const host = ctx as unknown as HostContext\n  const connection = resolveConnection({\n    endpoint: configText(config.endpoint),\n    apiKey: configText(config.apiKey),\n    account: configText(config.account),\n    user: configText(config.user),\n  })\n  const logger = host.logger\n  logger?.info?.(`[openviking-enhance] ${JSON.stringify(describeConnection(connection))}`)\n\n  const api = new OpenVikingApi(connection)\n  const studioPath = normalizeStudioPath(configText(config.studioPath))\n\n  const memoryRuntime = (): OpenVikingMemoryRuntime | null => {\n    try {\n      const value = host.get('openvikingMemory')\n      return value && typeof value === 'object' ? (value as OpenVikingMemoryRuntime) : null\n    } catch {\n      return null\n    }\n  }\n\n  const service = new CommitService({\n    api,\n    memoryRuntime,\n    cacheTtlMs: configNumber(config.cacheTtlMs, 2500),\n  })\n\n  const recall = new RecallService({\n    api,\n    commit: service,\n    cacheTtlMs: configNumber(config.recallCacheTtlMs, 15000),\n  })\n\n  const configPayload = async (): Promise<ApiResult<EnhanceConfig>> => {\n    const health = await api.health()\n    const warnings: PluginNotice[] = []\n    if (!health.ok) warnings.push({ code: 'unreachable', params: { endpoint: connection.endpoint, error: health.error ?? 'unknown' } })\n    if (!memoryRuntime()) {\n      warnings.push({ code: 'noMemoryPlugin' })\n    }\n    return {\n      ok: true,\n      endpoint: connection.endpoint,\n      studioUrl: `${connection.endpoint}${studioPath}`,\n      version: health.version,\n      healthy: health.ok,\n      account: connection.account,\n      user: connection.user,\n      warnings,\n    }\n  }\n\n  /**\n   * Refuse anything that is not a same-origin request from the loopback\n   * interface. These routes are not covered by the DSH web auth gate, and\n   * `/diff` returns memory bodies — see `trust-fence.ts` for what each check\n   * buys. Read-only is not a reason to skip this: the payload is private.\n   */\n  const guard = (req: IncomingMessage, res: ServerResponse): boolean => {\n    if (req.method !== 'GET') {\n      writeJson(res, 405, { ok: false, error: 'method-not-allowed' } satisfies ApiResult<never>)\n      return false\n    }\n    if (isTrustedLocalRequest(req)) return true\n    writeJson(res, 403, { ok: false, error: 'forbidden' } satisfies ApiResult<never>)\n    return false\n  }\n\n  const routes: WebRoute[] = [\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/config`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        writeJson(res, 200, await configPayload())\n      },\n    },\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/probe`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        // The configuration form's \"test\" button: it sends whatever the user has\n        // typed, so the endpoint is checked before anything is fetched. Loopback\n        // only — without that this route would be a general-purpose URL fetcher\n        // for anyone who can reach the plugin's port.\n        const candidate = parseLoopbackEndpoint(query(req).get('endpoint') ?? '')\n        if (candidate === null) {\n          writeJson(res, 400, {\n            ok: false,\n            error: 'endpoint-not-loopback',\n          } satisfies ApiResult<never>)\n          return\n        }\n        // The key is the one already in force, never the staged edit: a secret in\n        // a query string ends up in logs.\n        const health = await new OpenVikingApi({\n          endpoint: candidate.origin,\n          apiKey: connection.apiKey,\n          account: connection.account,\n          user: connection.user,\n        }).health()\n        writeJson(res, 200, { ok: true, reachable: health.ok, version: health.version, error: health.error })\n      },\n    },\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/status`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        const sessionId = query(req).get('sessionId') ?? ''\n        if (!sessionId) {\n          writeJson(res, 400, { ok: false, error: 'sessionId is required' } satisfies ApiResult<never>)\n          return\n        }\n        try {\n          const status = await service.status(sessionId, { fresh: query(req).get('fresh') === '1' })\n          writeJson(res, 200, { ok: true, status })\n        } catch (error) {\n          writeJson(res, 200, { ok: false, error: message(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/commits`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        const sessionId = query(req).get('sessionId') ?? ''\n        if (!sessionId) {\n          writeJson(res, 400, { ok: false, error: 'sessionId is required' } satisfies ApiResult<never>)\n          return\n        }\n        try {\n          // `summaries` bounds the timeline's fan-out: the popover asks for\n          // TIMELINE_DEFAULT on its poll and for more only when the user expands.\n          const requested = Number(query(req).get('summaries') ?? TIMELINE_DEFAULT)\n          const limit = Number.isFinite(requested) ? Math.min(Math.max(Math.trunc(requested), 0), TIMELINE_MAX) : TIMELINE_DEFAULT\n          // A user-triggered refresh (opening the popover, returning to the tab)\n          // skips the short status cache; ordinary polling keeps it.\n          const fresh = query(req).get('fresh') === '1'\n          const { status, tasks, summaries } = await service.commits(sessionId, limit, { fresh })\n          writeJson(res, 200, { ok: true, status, tasks, summaries })\n        } catch (error) {\n          writeJson(res, 200, { ok: false, error: message(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/diff`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        const params = query(req)\n        const sessionId = params.get('sessionId') ?? ''\n        const archiveUri = params.get('archive') ?? ''\n        if (!sessionId || !archiveUri) {\n          writeJson(res, 400, { ok: false, error: 'sessionId and archive are required' } satisfies ApiResult<never>)\n          return\n        }\n        const ovSessionId = service.ovSessionId(sessionId)\n        if (!isArchiveUriForSession(archiveUri, ovSessionId)) {\n          writeJson(res, 400, { ok: false, error: 'archive is not part of this session history' } satisfies ApiResult<never>)\n          return\n        }\n        try {\n          const diff = await service.diff(sessionId, archiveUri)\n          if (!diff) {\n            // Not an error: the archive exists but extraction has not written\n            // the diff yet. The UI shows this as \"extracting…\".\n            writeJson(res, 200, { ok: true, diff: null, pending: true })\n            return\n          }\n          writeJson(res, 200, { ok: true, diff, pending: false })\n        } catch (error) {\n          writeJson(res, 200, { ok: false, error: message(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/recall`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        const params = query(req)\n        const sessionId = params.get('sessionId') ?? ''\n        if (!sessionId) {\n          writeJson(res, 400, { ok: false, error: 'sessionId is required' } satisfies ApiResult<never>)\n          return\n        }\n        try {\n          // `query` is absent for the session's own last prompt; `limit` bounds\n          // each bucket, so a crafted request cannot ask for the whole library.\n          const requested = Number(params.get('limit') ?? RECALL_DEFAULT_LIMIT)\n          const limit = Number.isFinite(requested) ? requested : RECALL_DEFAULT_LIMIT\n          const payload = await recall.recall(sessionId, params.get('query') ?? undefined, limit, {\n            fresh: params.get('fresh') === '1',\n          })\n          writeJson(res, 200, { ok: true, recall: payload })\n        } catch (error) {\n          writeJson(res, 200, { ok: false, error: message(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: `${API_PREFIX}/recall/content`,\n      handler: async (req, res) => {\n        if (!guard(req, res)) return\n        const uri = query(req).get('uri') ?? ''\n        if (!uri) {\n          writeJson(res, 400, { ok: false, error: 'uri is required' } satisfies ApiResult<never>)\n          return\n        }\n        try {\n          // The reader refuses anything that is not a `viking://` path, so this\n          // route cannot be turned into a file read of the host.\n          const content = await recall.content(uri)\n          if ('error' in content) {\n            writeJson(res, 200, { ok: false, error: content.error })\n            return\n          }\n          writeJson(res, 200, { ok: true, content })\n        } catch (error) {\n          writeJson(res, 200, { ok: false, error: message(error) })\n        }\n      },\n    },\n  ]\n\n  host.effect(() => {\n    const disposers = routes.map((route) => host.webServer.register(route))\n    return () => {\n      for (const dispose of disposers.reverse()) dispose()\n    }\n  }, 'openviking-enhance: http routes')\n}\n\nfunction normalizeStudioPath(path: string | undefined): string {\n  // Belt and braces at the one place that took the whole entry down: its\n  // parameter is typed, but a plugin that fails to activate over a settings value\n  // is a worse outcome than a default Studio path. Anything that is not a string\n  // is treated as unset.\n  const raw = (typeof path === 'string' ? path.trim() : '') || '/studio/'\n  const withLeading = raw.startsWith('/') ? raw : `/${raw}`\n  return withLeading.endsWith('/') ? withLeading : `${withLeading}/`\n}\n\nfunction message(error: unknown): string {\n  return error instanceof Error ? error.message : String(error)\n}\n"
    },
    {
      "path": "src/host/commit-service.ts",
      "content": "/**\n * Per-session commit state, assembled from OpenViking rather than from DSH.\n *\n * Why not read the state from `@openviking/dsh-memory-plugin`? It exposes\n * `openvikingMemory` (a plain `ctx.provide` value), but that object carries no\n * commit status, no history and no emitter, and the plugin drops the commit\n * response's `task_id`/`archive_uri` while logging only at `debug` — which the\n * desktop app filters out. Every fact below therefore comes from the server,\n * which also makes this half immune to plugin upgrades.\n *\n * Two seams into the plugin are still used, both optional:\n *   - `states.get(sessionId).ovSessionId` — the authoritative OpenViking\n *     session key (falls back to `dsh-<sessionId>`);\n *   - `states.get(sessionId).config.peerId` — the actor peer, required for\n *     peer-scoped (git-repo) workspaces, else the memory listing comes back\n *     empty.\n */\nimport type {\n  ArchiveFailure,\n  ArchiveState,\n  ArchiveSummary,\n  ArchiveTerminal,\n  CommitArchive,\n  CommitPhase,\n  CommitStatus,\n  MemoryDiff,\n  MemoryDiffEntry,\n  MemoryDiffSummary,\n} from '../shared/protocol.ts'\nimport type { OpenVikingApi, OvCommitTask } from './openviking-api.ts'\n\n/** The slice of `@openviking/dsh-memory-plugin`'s runtime this plugin reads. */\nexport interface OpenVikingMemoryRuntime {\n  states?: Map<unknown, { ovSessionId?: string; config?: { peerId?: string; commitTokenThreshold?: number } }>\n}\n\n/** Shape of `memory_diff.json` on the server. */\ninterface RawMemoryDiff {\n  archive_uri?: string\n  extracted_at?: string\n  operations?: {\n    adds?: RawDiffEntry[]\n    updates?: RawDiffEntry[]\n    deletes?: RawDiffEntry[]\n  }\n  summary?: { total_adds?: number; total_updates?: number; total_deletes?: number; total_skipped?: number }\n}\n\ninterface RawDiffEntry {\n  uri?: string\n  memory_type?: string\n  before?: string\n  after?: string\n  deleted_content?: string\n}\n\n/** Shape of `.failed.json` on the server. */\nexport interface RawFailedMarker {\n  stage?: string\n  error?: string\n  failed_at?: string\n  skipped?: boolean\n  completed_memory_steps?: Record<string, string[]>\n}\n\n/** One archive's terminal state, read once and cached when it is final. */\ninterface ArchiveProbe {\n  state: ArchiveState\n  failure: ArchiveFailure | null\n  diff: MemoryDiff | null\n  /** A real `.done` / `.failed.json` was seen (not just a legacy diff). */\n  markers: boolean\n}\n\n/** How long a pending archive is left alone before its markers are re-probed. */\nconst PENDING_ARCHIVE_RETRY_MS = 10_000\n\nexport interface CommitServiceOptions {\n  api: OpenVikingApi\n  /** Resolve the mounted OpenViking plugin runtime, or null when absent. */\n  memoryRuntime: () => OpenVikingMemoryRuntime | null\n  /** Status cache TTL; the client polls, so this keeps the server calm. */\n  cacheTtlMs?: number\n  /** How long a still-pending archive is left alone before its markers are re-probed. */\n  pendingArchiveRetryMs?: number\n}\n\nexport class CommitService {\n  private readonly cache = new Map<string, { at: number; value: CommitStatus }>()\n  /**\n   * One probe per archive. `memory_diff.json`, `.done` and `.failed.json` are\n   * immutable once written, so a terminal probe is cached for the process\n   * lifetime. A pending archive is re-probed after `pendingRetryMs` — extraction\n   * may still be running — instead of on every poll.\n   */\n  private readonly probes = new Map<string, ArchiveProbe>()\n  private readonly probeRetryAt = new Map<string, number>()\n  /**\n   * One in-flight read per session. Several GUI tabs (or a fast poll and a\n   * user-triggered refresh) then share one upstream round trip instead of\n   * multiplying it.\n   */\n  private readonly inflight = new Map<string, Promise<CommitStatus>>()\n  private readonly options: CommitServiceOptions\n  private readonly cacheTtlMs: number\n  private readonly pendingRetryMs: number\n\n  // Plain field assignment rather than a constructor parameter property: the\n  // latter is TypeScript-only syntax that Node's type stripping cannot erase,\n  // which would make this module unimportable from the unit tests.\n  constructor(options: CommitServiceOptions) {\n    this.options = options\n    this.cacheTtlMs = options.cacheTtlMs ?? 2500\n    this.pendingRetryMs = options.pendingArchiveRetryMs ?? PENDING_ARCHIVE_RETRY_MS\n  }\n\n  /** OpenViking session key for a DSH session. */\n  ovSessionId(sessionId: string): string {\n    const fromPlugin = this.options.memoryRuntime()?.states?.get(sessionId)?.ovSessionId\n    return typeof fromPlugin === 'string' && fromPlugin.length > 0 ? fromPlugin : `dsh-${sessionId}`\n  }\n\n  /**\n   * Actor peer, when the OpenViking plugin knows it.\n   *\n   * Public because peer-scoped routing is not a commit concern: the recall\n   * service needs the same identity to search the same peer's memories.\n   */\n  actorPeer(sessionId: string): string | undefined {\n    const peer = this.options.memoryRuntime()?.states?.get(sessionId)?.config?.peerId\n    return typeof peer === 'string' && peer.length > 0 ? peer : undefined\n  }\n\n  /** Effective commit threshold; null when the OpenViking plugin is not mounted. */\n  private threshold(sessionId: string): number | null {\n    const value = this.options.memoryRuntime()?.states?.get(sessionId)?.config?.commitTokenThreshold\n    return typeof value === 'number' && Number.isFinite(value) ? value : null\n  }\n\n  async status(sessionId: string, options: { fresh?: boolean } = {}): Promise<CommitStatus> {\n    const cached = this.cache.get(sessionId)\n    if (!options.fresh && cached && Date.now() - cached.at < this.cacheTtlMs) return cached.value\n\n    // One upstream read per session at a time. Several GUI tabs, or a poll and a\n    // user-triggered refresh, then share one round trip instead of multiplying it.\n    const running = this.inflight.get(sessionId)\n    if (running) return running\n\n    const work = this.readStatus(sessionId, options.fresh === true)\n      .then((value) => {\n        this.cache.set(sessionId, { at: Date.now(), value })\n        return value\n      })\n      .finally(() => {\n        this.inflight.delete(sessionId)\n      })\n    this.inflight.set(sessionId, work)\n    return work\n  }\n\n  /** One uncached upstream read; `status()` owns caching and in-flight sharing. */\n  private async readStatus(sessionId: string, fresh: boolean): Promise<CommitStatus> {\n    const ovSessionId = this.ovSessionId(sessionId)\n    const request = { actorPeerId: this.actorPeer(sessionId) }\n    // Sequential, not parallel: the history path must be derived from the\n    // session's own `uri`, which only the first call can answer. It costs one\n    // round trip (~7 ms) and removes a whole class of \"never committed\" lies for\n    // sessions owned by another user or peer.\n    const meta = await this.options.api.getSession(ovSessionId, request)\n    const historyUri = resolveSessionUri(meta.result, ovSessionId, this.options.api.user)\n    const history = await this.options.api.listHistory(historyUri, request)\n\n    const pendingTokens = meta.result?.pending_tokens ?? 0\n    const commitCount = meta.result?.commit_count ?? 0\n    const threshold = this.threshold(sessionId)\n    const archives = (history.result ?? [])\n      .filter((entry) => entry.isDir)\n      .map<CommitArchive>((entry) => ({\n        archiveId: entry.uri.split('/').pop() ?? entry.uri,\n        archiveUri: entry.uri,\n        modTime: entry.modTime ?? null,\n      }))\n      .sort((a, b) => a.archiveId.localeCompare(b.archiveId))\n\n    // The newest archive's terminal marker is the durable fact behind the pill.\n    // `commit_count` advances when the archive is written, so counts alone cannot\n    // tell \"extraction still running\" from \"extraction failed\".\n    const newest = archives[archives.length - 1]\n    const latestProbe = newest === undefined ? null : await this.probeArchive(sessionId, newest.archiveUri, { fresh })\n    const latest: ArchiveTerminal | null =\n      newest !== undefined && latestProbe !== null\n        ? {\n            archiveUri: newest.archiveUri,\n            state: latestProbe.state,\n            failure: latestProbe.failure,\n            markers: latestProbe.markers,\n          }\n        : null\n    const phase = derivePhase({\n      metaOk: meta.ok,\n      commitCount,\n      pendingTokens,\n      archiveCount: archives.length,\n      latestState: latestProbe?.state ?? null,\n    })\n\n    return {\n      sessionId,\n      ovSessionId,\n      pendingTokens,\n      threshold,\n      ratio: threshold && threshold > 0 ? Math.min(1, pendingTokens / threshold) : 0,\n      commitCount,\n      lastCommitAt: meta.result?.last_commit_at ?? null,\n      phase,\n      latest,\n      archives,\n    }\n  }\n\n  /**\n   * Commit records for a session: one per archive, oldest first.\n   *\n   * Archives and their terminal markers are the durable record — task records are\n   * pruned by the server, so they are only consulted to label a commit that is\n   * still being extracted (and as the fallback on servers without markers).\n   */\n  async commits(\n    sessionId: string,\n    summaryLimit: number,\n    options: { fresh?: boolean } = {},\n  ): Promise<{ status: CommitStatus; tasks: OvCommitTask[]; summaries: ArchiveSummary[] }> {\n    const status = await this.status(sessionId, options)\n    const tasks = await this.options.api.listCommitTasks(status.ovSessionId, {\n      actorPeerId: this.actorPeer(sessionId),\n    })\n    const summaries = await this.summaries(sessionId, status.archives, summaryLimit, options)\n    return { status, tasks: tasks.result ?? [], summaries }\n  }\n\n  /**\n   * Read one archive's `memory_diff.json`, through the same cached probe the\n   * timeline uses. A pending archive returns null; a failed one may still have a\n   * partial diff, which is returned as-is — the caller shows the failure too.\n   */\n  async diff(sessionId: string, archiveUri: string): Promise<MemoryDiff | null> {\n    const probe = await this.probeArchive(sessionId, archiveUri)\n    return probe.diff\n  }\n\n  /**\n   * Terminal states and counts for the newest `limit` archives, newest first.\n   *\n   * A terminal probe is memoized for the process lifetime; a pending one is\n   * re-probed only after `pendingRetryMs`, so a fast poll during extraction does\n   * not fan out to every archive on every tick.\n   */\n  async summaries(\n    sessionId: string,\n    archives: CommitArchive[],\n    limit: number,\n    options: { fresh?: boolean } = {},\n  ): Promise<ArchiveSummary[]> {\n    const count = Math.max(0, Math.trunc(limit))\n    if (count === 0) return []\n    const wanted = archives.slice(-count).reverse()\n    return Promise.all(\n      wanted.map(async (archive): Promise<ArchiveSummary> => {\n        const probe = await this.probeArchive(sessionId, archive.archiveUri, options)\n        return {\n          archiveUri: archive.archiveUri,\n          summary: probe.diff?.summary ?? null,\n          state: probe.state,\n          failure: probe.failure,\n        }\n      }),\n    )\n  }\n\n  /**\n   * Read one archive's terminal marker and diff, with an in-memory cache.\n   *\n   * Marker files are the durable record of the commit's extraction: `.done`\n   * means it finished, `.failed.json` means it failed (and carries the server's\n   * own reason). `memory_diff.json` is read in both cases because the timeline\n   * counts can be partially written even on failure. Only a `pending` or\n   * `unknown` archive is re-probed later.\n   */\n  private async probeArchive(\n    sessionId: string,\n    archiveUri: string,\n    options: { fresh?: boolean } = {},\n  ): Promise<ArchiveProbe> {\n    const cached = this.probes.get(archiveUri)\n    if (cached) return cached\n    if (!options.fresh && (this.probeRetryAt.get(archiveUri) ?? 0) > Date.now()) {\n      return { state: 'pending', failure: null, diff: null, markers: false }\n    }\n\n    const request = { actorPeerId: this.actorPeer(sessionId) }\n    const base = archiveUri.replace(/\\/+$/, '')\n    const done = await this.options.api.readText(`${base}/.done`, request)\n    const donePresent = done.ok && done.result !== null\n    const doneUnreadable = !done.ok && done.status !== 404\n    const [diffResponse, failedResponse] = await Promise.all([\n      this.options.api.readJson<RawMemoryDiff>(`${base}/memory_diff.json`, request),\n      donePresent || doneUnreadable\n        ? Promise.resolve(null)\n        : this.options.api.readJson<RawFailedMarker>(`${base}/.failed.json`, request),\n    ])\n\n    const diff = diffResponse.ok && diffResponse.result ? normalizeDiff(archiveUri, diffResponse.result) : null\n    const failure =\n      failedResponse !== null && failedResponse.ok && failedResponse.result\n        ? normalizeFailure(failedResponse.result)\n        : null\n    const diffUnreadable = !diffResponse.ok && diffResponse.status !== 404\n    const failedUnreadable = failedResponse !== null && !failedResponse.ok && failedResponse.status !== 404\n\n    let state: ArchiveState\n    if (donePresent) state = 'done'\n    else if (failure !== null) state = 'failed'\n    else if (doneUnreadable || diffUnreadable || failedUnreadable) state = 'unknown'\n    // Legacy servers without terminal markers only wrote memory_diff.json; a\n    // readable diff is the only success signal they offer.\n    else if (diff !== null) state = 'done'\n    else state = 'pending'\n\n    const probe: ArchiveProbe = { state, failure, diff, markers: donePresent || failure !== null }\n    if (state === 'done' || state === 'failed') {\n      this.probes.set(archiveUri, probe)\n      this.probeRetryAt.delete(archiveUri)\n      return probe\n    }\n    this.probeRetryAt.set(archiveUri, Date.now() + this.pendingRetryMs)\n    return probe\n  }\n}\n\n/**\n * Guard for the `archive` parameter of the diff route: the browser half may only\n * as